<?php
declare(strict_types=1);namespace App\Controllers;use App\Exceptions\NotFoundException;use App\Support\{Request,Response};
final class AdminWithdrawalController extends Controller {public function index(Request $r):Response{$data=app('withdrawals')->queue($r->all(),max(1,(int)$r->input('page',1)));return $this->view('admin/withdrawals',['title'=>'Withdrawals','withdrawals'=>$data['items']],'layouts.admin');}public function show(Request $r):Response{$w=app('database')?->one('SELECT w.*,u.email,m.name method_name FROM withdrawal_requests w JOIN users u ON u.id=w.user_id JOIN withdrawal_methods m ON m.id=w.withdrawal_method_id WHERE w.id=?',[(int)$r->route('withdrawal')]);if(!$w)throw new NotFoundException('Withdrawal not found.');return $this->view('admin/withdrawal-detail',['title'=>'Withdrawal '.$w['reference'],'withdrawal'=>$w,'values'=>app('withdrawals')->values((int)$w['id'])],'layouts.admin');}public function action(Request $r):Response{try{app('withdrawals')->transition((int)$r->route('withdrawal'),(int)$_SESSION['user_id'],(string)$r->input('action'),(string)$r->input('reason'),(string)$r->input('notes'),(string)$r->input('payout_reference'));$this->flash('success','Withdrawal updated.');}catch(\Throwable $e){$this->flash('error',$e->getMessage());}return $this->redirect('admin.withdrawals.show',['withdrawal'=>(int)$r->route('withdrawal')]);}}
